import logging
import requests
from tenacity import (
    retry, stop_after_attempt, wait_exponential, wait_random,
    retry_if_exception_type, before_sleep_log,
)

logger = logging.getLogger(__name__)

class RetryableError(Exception):
    """Raised only for transient failures that are worth retrying."""

# base=1s, doubling, capped at 30s, plus 0-2s of jitter; give up after 5 tries
@retry(
    stop=stop_after_attempt(5),
    wait=wait_exponential(multiplier=1, max=30) + wait_random(0, 2),
    retry=retry_if_exception_type(RetryableError),
    before_sleep=before_sleep_log(logger, logging.WARNING),
    reraise=True,
)
def fetch_price(sku: str) -> dict:
    resp = requests.get(f"https://pricing.internal/price/{sku}", timeout=5)
    # Transient: throttling / server errors -> retry
    if resp.status_code in (429, 500, 502, 503, 504):
        raise RetryableError(f"transient {resp.status_code} for {sku}")
    # Terminal: bad request / not found -> do NOT retry, let it raise
    resp.raise_for_status()
    return resp.json()


def process(sku: str):
    try:
        return fetch_price(sku)
    except RetryableError:
        # Exhausted all transient retries -> treat as poison, send to DLQ
        send_to_dlq(sku, reason="pricing_unavailable_after_retries")
    except requests.HTTPError as e:
        # Terminal error (e.g. 400/404) -> straight to DLQ, no retries wasted
        send_to_dlq(sku, reason=f"terminal_{e.response.status_code}")

import json, time, traceback
from confluent_kafka import Consumer, Producer

SOURCE_TOPIC = "orders"
DLQ_TOPIC = "orders.DLQ"
MAX_ATTEMPTS = 4

consumer = Consumer({
    "bootstrap.servers": "broker:9092",
    "group.id": "orders-consumer",
    "enable.auto.commit": False,
    "auto.offset.reset": "earliest",
})
producer = Producer({"bootstrap.servers": "broker:9092"})
consumer.subscribe([SOURCE_TOPIC])

class TerminalError(Exception):
    pass

def handle(record: dict):
    # Terminal example: schema violation -> never retry
    if "order_id" not in record:
        raise TerminalError("missing required field order_id")
    write_to_warehouse(record)  # must be idempotent (MERGE on order_id)

def to_dlq(msg, error: str):
    producer.produce(
        DLQ_TOPIC,
        key=msg.key(),
        value=msg.value(),  # preserve raw bytes for replay
        headers=[
            ("error", error.encode()),
            ("source_topic", SOURCE_TOPIC.encode()),
            ("source_partition", str(msg.partition()).encode()),
            ("source_offset", str(msg.offset()).encode()),
        ],
    )
    producer.flush()

while True:
    msg = consumer.poll(1.0)
    if msg is None:
        continue
    if msg.error():
        continue
    try:
        record = json.loads(msg.value())
    except json.JSONDecodeError as e:
        to_dlq(msg, f"JsonParseException: {e}")  # poison: unparseable
        consumer.commit(msg)
        continue

    for attempt in range(1, MAX_ATTEMPTS + 1):
        try:
            handle(record)
            consumer.commit(msg)
            break
        except TerminalError as e:
            to_dlq(msg, f"terminal: {e}")   # never retry terminal errors
            consumer.commit(msg)
            break
        except Exception as e:            # transient: retry with backoff
            if attempt == MAX_ATTEMPTS:
                to_dlq(msg, f"exhausted after {attempt}: {e}\n{traceback.format_exc()}")
                consumer.commit(msg)
            else:
                time.sleep(min(30, 2 ** attempt))  # exponential backoff

from datetime import timedelta
from airflow.decorators import dag, task
from airflow.utils.dates import days_ago

default_args = {
    "retries": 4,
    "retry_delay": timedelta(seconds=30),
    "retry_exponential_backoff": True,   # 30s, 60s, 120s, 240s ...
    "max_retry_delay": timedelta(minutes=10),  # cap the backoff
}

@dag(schedule="@hourly", start_date=days_ago(1),
     default_args=default_args, catchup=False, tags=["reliability"])
def orders_pipeline():

    @task(retries=4, retry_exponential_backoff=True,
          retry_delay=timedelta(seconds=30),
          max_retry_delay=timedelta(minutes=10))
    def load_from_api():
        import requests
        r = requests.get("https://pricing.internal/batch", timeout=10)
        if r.status_code in (429, 500, 502, 503, 504):
            raise RuntimeError(f"transient {r.status_code}")  # -> retried
        r.raise_for_status()  # 4xx -> fails fast, no benefit from retry
        return r.json()

    @task
    def write_dlq_on_bad_rows(rows: list):
        good, bad = [], []
        for row in rows:
            (good if "order_id" in row else bad).append(row)
        if bad:
            # Quarantine poison rows to a durable DLQ table for replay
            write_rows("orders_dlq", bad)
        write_rows("orders_trusted", good)
        return {"loaded": len(good), "dlq": len(bad)}

    write_dlq_on_bad_rows(load_from_api())

orders_pipeline()
